SELECT COUNT(*) FROM users as u, postHistory as ph, posts as p, votes as v WHERE u.Id = p.OwnerUserId AND p.Id = v.PostId AND p.Id = ph.PostId AND u.Views>=0 AND u.Views<=34 AND u.UpVotes>=0 AND ph.CreationDate>=CAST('2010-07-21 00:44:08' AS TIMESTAMP) AND p.ViewCount>=0 AND p.CommentCount>=0 AND v.VoteTypeId=2
